 27	public class Database {
 28	    private static final String DB_URL = System.getenv("DB_URL");
 29	    private static final String DB_USER = System.getenv("DB_USER");
 30	    private static final String DB_PASSWORD = System.getenv("DB_PASSWORD");
 31	
 32	    public static Connection getConnection() throws SQLException {
 33	        return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
 34	    }
 35	
 36	    public static void initialize() {
 37	        try {
 38	            Class.forName("org.postgresql.Driver");
 39	            createSchema();
 40	            insertRooms();
 41	        } catch (ClassNotFoundException | SQLException e) {
 42	            throw new RuntimeException(e);
 43	        }
 44	    }
 45	
 46	    private static void createSchema() throws SQLException {
 47	        try (Connection conn = getConnection()) {
 48	            conn.setAutoCommit(true);
 49	
 50	            String createRoomsTable = """
 51	                    CREATE TABLE IF NOT EXISTS rooms (
 52	                        number INTEGER PRIMARY KEY,
 53	                        type VARCHAR(50) NOT NULL,
 54	                        capacity INTEGER NOT NULL,
 55	                        nightly_rate NUMERIC(10, 2) NOT NULL
 56	                    )
 57	                    """;
 58	
 59	            String createReservationsTable = """
 60	                    CREATE TABLE IF NOT EXISTS reservations (
 61	                        id SERIAL PRIMARY KEY,
 62	                        room_number INTEGER NOT NULL REFERENCES rooms(number),
 63	                        guest_name VARCHAR(255) NOT NULL,
 64	                        guest_email VARCHAR(255) NOT NULL,
 65	                        guest_cpf VARCHAR(20) NOT NULL,
 66	                        check_in DATE NOT NULL,
 67	                        check_out DATE NOT NULL,
 68	                        guests INTEGER NOT NULL,
 69	                        rate_plan VARCHAR(50) NOT NULL,
 70	                        nights INTEGER NOT NULL,
 71	                        subtotal NUMERIC(10, 2) NOT NULL,
 72	                        discount NUMERIC(10, 2) NOT NULL,
 73	                        total NUMERIC(10, 2) NOT NULL,
 74	                        status VARCHAR(50) NOT NULL,
 75	                        amount_paid NUMERIC(10, 2) NOT NULL DEFAULT 0,
 76	                        refund NUMERIC(10, 2),
 77	                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
 78	                    )
 79	                    """;
 80	
 81	            String createMessagesTable = """
 82	                    CREATE TABLE IF NOT EXISTS messages (
 83	                        id SERIAL PRIMARY KEY,
 84	                        channel VARCHAR(50) NOT NULL,
 85	                        recipient VARCHAR(255) NOT NULL,
 86	                        subject VARCHAR(255) NOT NULL,
 87	                        body TEXT NOT NULL,
 88	                        status VARCHAR(50) NOT NULL,
 89	                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
 90	                    )
 91	                    """;
 92	
 93	            try (Statement stmt = conn.createStatement()) {
 94	                stmt.execute(createRoomsTable);
 95	                stmt.execute(createReservationsTable);
 96	                stmt.execute(createMessagesTable);
 97	            }
 98	        }
 99	    }
100	
101	    private static void insertRooms() throws SQLException {
102	        try (Connection conn = getConnection()) {
103	            String checkRooms = "SELECT COUNT(*) FROM rooms";
104	            try (Statement stmt = conn.createStatement();
105	                 ResultSet rs = stmt.executeQuery(checkRooms)) {
106	                rs.next();
107	                if (rs.getInt(1) == 0) {
108	                    String insertRooms = """
109	                            INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES
110	                            (101, 'STANDARD', 2, 249.90),
111	                            (102, 'STANDARD', 2, 249.90),
112	                            (201, 'DELUXE', 3, 389.90),
113	                            (202, 'DELUXE', 3, 389.90),
114	                            (301, 'SUITE', 4, 579.90)
115	                            """;
116	                    try (Statement insertStmt = conn.createStatement()) {
117	                        insertStmt.execute(insertRooms);
118	                    }
119	                }
120	            }
121	        }
122	    }
123	}
