     1	package com.pousadamarealta.service;
     2	
     3	import com.pousadamarealta.model.Message;
     4	import com.pousadamarealta.repository.MessageRepository;
     5	import java.util.ArrayList;
     6	import java.util.List;
     7	
     8	public class MessageService {
     9	    private static final String ARCHIVE_EMAIL = "arquivo@pousadamarealta.com.br";
    10	    private static final String TEST_EMAIL = "testes@pousadamarealta.com.br";
    11	    private static final boolean TEST_MODE = "true".equalsIgnoreCase(System.getenv("HOTEL_TEST_MODE"));
    12	
    13	    public static class SendResult {
    14	        public Message original;
    15	        public Message archiveCopy;
    16	
    17	        public SendResult(Message original, Message archiveCopy) {
    18	            this.original = original;
    19	            this.archiveCopy = archiveCopy;
    20	        }
    21	    }
    22	
    23	    public static SendResult sendMessage(String channel, String originalTo, String subject, String body) throws java.sql.SQLException {
    24	        Message original = new Message();
    25	        original.channel = channel;
    26	
    27	        if (!isValidEmail(originalTo)) {
    28	            original.to = originalTo;
    29	            original.subject = subject;
    30	            original.body = body;
    31	            original.status = "BLOCKED";
    32	            MessageRepository.save(original);
    33	            return new SendResult(original, null);
    34	        }
    35	
    36	        String finalTo = originalTo;
    37	        String finalSubject = subject;
    38	        String finalBody = body;
    39	
    40	        if (TEST_MODE) {
    41	            finalTo = TEST_EMAIL;
    42	            finalSubject = "[TESTE] " + subject;
    43	            finalBody = "Destinatário original: " + originalTo + "\n\n" + body;
    44	        }
    45	
    46	        original.to = finalTo;
    47	        original.subject = finalSubject;
    48	        original.body = finalBody;
    49	        original.status = "SENT";
    50	        MessageRepository.save(original);
    51	
    52	        Message archiveCopy = null;
    53	        if (!TEST_MODE) {
    54	            archiveCopy = new Message();
    55	            archiveCopy.channel = channel;
    56	            archiveCopy.to = ARCHIVE_EMAIL;
    57	            archiveCopy.subject = "[Cópia] " + subject;
    58	            archiveCopy.body = body;
    59	            archiveCopy.status = "SENT";
    60	            MessageRepository.save(archiveCopy);
    61	        }
    62	
    63	        return new SendResult(original, archiveCopy);
    64	    }
    65	
    66	    private static boolean isValidEmail(String email) {
    67	        if (!email.contains("@")) return false;
    68	
    69	        int atIndex = email.indexOf("@");
    70	        if (atIndex != email.lastIndexOf("@")) return false;
    71	
    72	        String before = email.substring(0, atIndex);
    73	        if (before.isEmpty()) return false;
    74	
    75	        String after = email.substring(atIndex + 1);
    76	        if (!after.contains(".") || after.endsWith(".")) return false;
    77	
    78	        return true;
    79	    }
    80	}
