     7	import java.util.List;
     8	
     9	public class MessageRepository {
    10	    public static void save(Message message) throws SQLException {
    11	        try (Connection conn = Database.getConnection();
    12	             PreparedStatement stmt = conn.prepareStatement(
    13	                     "INSERT INTO messages (channel, recipient, subject, body, status) VALUES (?, ?, ?, ?, ?)",
    14	                     Statement.RETURN_GENERATED_KEYS)) {
    15	            stmt.setString(1, message.channel);
    16	            stmt.setString(2, message.to);
    17	            stmt.setString(3, message.subject);
    18	            stmt.setString(4, message.body);
    19	            stmt.setString(5, message.status);
    20	
    21	            stmt.executeUpdate();
    22	            try (ResultSet rs = stmt.getGeneratedKeys()) {
    23	                if (rs.next()) {
    24	                    message.id = rs.getLong(1);
    25	                }
    26	            }
    27	        }
    28	    }
    29	
    30	    public static List<Message> findAll() throws SQLException {
    31	        List<Message> messages = new ArrayList<>();
    32	        try (Connection conn = Database.getConnection();
    33	             Statement stmt = conn.createStatement();
    34	             ResultSet rs = stmt.executeQuery(
    35	                     "SELECT id, channel, recipient, subject, body, status FROM messages ORDER BY id")) {
    36	            while (rs.next()) {
    37	                Message m = new Message();
    38	                m.id = rs.getLong("id");
    39	                m.channel = rs.getString("channel");
    40	                m.to = rs.getString("recipient");
    41	                m.subject = rs.getString("subject");
    42	                m.body = rs.getString("body");
    43	                m.status = rs.getString("status");
    44	                messages.add(m);
    45	            }
    46	        }
    47	        return messages;
    48	    }
    49	}
