     1	package com.pousadamarealta.service;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.time.LocalDate;
     6	import java.time.temporal.ChronoUnit;
     7	
     8	public class PricingService {
     9	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
    10	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT_RATE = new BigDecimal("0.15");
    11	
    12	    public static int calculateNights(LocalDate checkIn, LocalDate checkOut) {
    13	        return (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    14	    }
    15	
    16	    public static BigDecimal calculateNightlyRate(BigDecimal baseRate, LocalDate date) {
    17	        if (isHighSeason(date)) {
    18	            return baseRate.multiply(HIGH_SEASON_MULTIPLIER).setScale(2, RoundingMode.HALF_EVEN);
    19	        }
    20	        return baseRate.setScale(2, RoundingMode.HALF_EVEN);
    21	    }
    22	
    23	    private static boolean isHighSeason(LocalDate date) {
    24	        int month = date.getMonthValue();
    25	        int day = date.getDayOfMonth();
    26	
    27	        // December 15 to end of February
    28	        if ((month == 12 && day >= 15) || month == 1 || month == 2) {
    29	            return true;
    30	        }
    31	
    32	        // Entire July
    33	        return month == 7;
    34	    }
    35	
    36	    public static class PriceCalculation {
    37	        public BigDecimal subtotal;
    38	        public BigDecimal discount;
    39	        public BigDecimal total;
    40	
    41	        public PriceCalculation(BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
    42	            this.subtotal = subtotal;
    43	            this.discount = discount;
    44	            this.total = total;
    45	        }
    46	    }
    47	
    48	    public static PriceCalculation calculatePrice(BigDecimal baseRate, LocalDate checkIn,
    49	                                                   LocalDate checkOut, String ratePlan) {
    50	        int nights = calculateNights(checkIn, checkOut);
    51	        BigDecimal subtotal = BigDecimal.ZERO;
    52	
    53	        LocalDate current = checkIn;
    54	        for (int i = 0; i < nights; i++) {
    55	            subtotal = subtotal.add(calculateNightlyRate(baseRate, current));
    56	            current = current.plusDays(1);
    57	        }
    58	
    59	        BigDecimal discount = BigDecimal.ZERO;
    60	        if ("NON_REFUNDABLE".equals(ratePlan)) {
    61	            discount = subtotal.multiply(NON_REFUNDABLE_DISCOUNT_RATE)
    62	                    .setScale(2, RoundingMode.HALF_EVEN);
    63	        }
    64	
    65	        BigDecimal total = subtotal.subtract(discount);
    66	
    67	        return new PriceCalculation(subtotal, discount, total);
    68	    }
    69	}
