   278	    private static String generateReceipt(Reservation reservation, Room room) {
   279	        String nighsStr = reservation.nights == 1 ? "1 diária" : reservation.nights + " diárias";
   280	        StringBuilder receipt = new StringBuilder();
   281	        receipt.append("Comprovante de reserva nº ").append(reservation.id).append("\n");
   282	        receipt.append("Hóspede: ").append(reservation.guestName).append(" (CPF ").append(formatCpf(reservation.guestCpf)).append(")\n");
   283	        receipt.append("Quarto: ").append(reservation.roomNumber).append(" (").append(room.type).append(")\n");
   284	        receipt.append("Entrada: ").append(formatDate(reservation.checkIn)).append(" | ");
   285	        receipt.append("Saída: ").append(formatDate(reservation.checkOut)).append(" | ").append(nighsStr).append("\n");
   286	        receipt.append("Diárias: ").append(formatMoney(reservation.subtotal)).append("\n");
   287	        if (reservation.discount.compareTo(java.math.BigDecimal.ZERO) > 0) {
   288	            receipt.append("Desconto: ").append(formatMoney(reservation.discount)).append("\n");
   289	        }
   290	        receipt.append("Total: ").append(formatMoney(reservation.total)).append("\n");
   291	        return receipt.toString();
   292	    }
